head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > focusMove]<br/>GridView 컴포넌트에서 키보드를 통한 포커스 이동을 허용할지 설정합니다.",
    "validation" : [
        "'true'(기본값) 설정 시 상/하/좌/우 방향키와 Home/End, PageUp/PageDown, Enter, Tab 키로 포커스를 이동할 수 있습니다.",
        "'false' 설정 시 상/하/좌/우 방향키와 Home/End, PageUp/PageDown, Enter, Tab 키로 포커스를 이동할 수 없습니다. (senseReader=true 일때 Tab 키에 의한 포커스 이동은 허용합니다.)",
        "'vertical' 설정 시 상/하 방향키와 PageUp/PageDown 키로 포커스를 이동할 수 있으며, enterKeyMove 속성값에 따라 Enter 키로 포커스를 이동할 수 있습니다.",
        "'horizontal' 설정 시 좌/우 방향키와 Home/End, Tab 키로 포커스를 이동할 수 있으며, Enter 키로 포커스를 이동할 수 없습니다.",
        "accessibility=true 이면 focusMove 는 false 로 동작합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - con_focusMove     : 정적 select1 (미설정/true/false/vertical/horizontal) → getValue()
//                        · 미설정('') 이면 focusMove 속성 자체를 추가하지 않음(기본 true 동작)
//  - con_accessibility : 공통 gdl_boolean → getText() (@spec5: true 시 focusMove false 로 동작)
//  - con_enterKeyMove  : 공통 gdl_boolean → getText() (vertical 일 때 Enter 이동 여부 검증 #3)
//                        · 미설정('') 이면 속성 제외, 'true' → enterKeyMove="down", 'false' → enterKeyMove="none"
//  - focusMode="cell" 고정 : 키보드 셀 포커스 이동 확인용
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let vFocusMove     = con_focusMove.getValue();
    let vAccessibility = con_accessibility.getText();
    let vEnterKeyMove  = con_enterKeyMove.getText();

    // focusMode 는 키보드 포커스 이동 확인을 위해 cell 고정
    let properties = {
        focusMode : "cell"
    };

    // focusMove : 미설정('') 이면 속성 자체를 추가하지 않음(기본 true)
    if (vFocusMove !== '') {
        properties.focusMove = vFocusMove;
    }

    // accessibility : '' 미설정 시 속성 제외
    if (vAccessibility === 'true') {
        properties.accessibility = true;
    } else if (vAccessibility === 'false') {
        properties.accessibility = false;
    }

    // enterKeyMove : vertical 일 때 Enter 이동 여부 검증용
    //  · 'true' → "down"(아래 이동), 'false' → "none"(이동 없음), '' → 속성 제외(기본 down)
    if (vEnterKeyMove === 'true') {
        properties.enterKeyMove = "down";
    } else if (vEnterKeyMove === 'false') {
        properties.enterKeyMove = "none";
    }

    let cList = $c.gcm.createCList(properties);

    let lblDesc = '현재 설정 → focusMove=' + (vFocusMove === '' ? '(미설정=기본 true)' : vFocusMove)
        + ', accessibility=' + (vAccessibility === '' ? '(미설정)' : vAccessibility)
        + ', enterKeyMove=' + (vEnterKeyMove === '' ? '(미설정)' : (vEnterKeyMove === 'true' ? 'down' : 'none'))
        + ' / 셀 클릭 후 방향키/Enter/Tab/Home/End/PageUp/PageDown 입력 시 포커스 이동 동작 확인 (현재 포커스 셀은 아래에 출력)';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    // 포커스 이동 확인용 dataList 생성 (col1~col4, 6행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 6);
    scwin.fillData();

    // target 생성 (4컬럼 Body 그리드)
    await scwin.createGridView(cList);
}



// 포커스 이동 확인용 데이터 (6행)
scwin.fillData = function () {
    let rows = [
        { col1: "A1", col2: "B1", col3: "C1", col4: "D1" },
        { col1: "A2", col2: "B2", col3: "C2", col4: "D2" },
        { col1: "A3", col2: "B3", col3: "C3", col4: "D3" },
        { col1: "A4", col2: "B4", col3: "C4", col4: "D4" },
        { col1: "A5", col2: "B5", col3: "C5", col4: "D5" },
        { col1: "A6", col2: "B6", col3: "C6", col4: "D6" }
    ];
    dlt_bind.setJSON(rows, false);
}



// gridView 동적 생성
//  - oncellindexchange : 방향키/Enter/Tab 등으로 포커스 셀이 변경될 때마다 현재 포커스 셀 출력
scwin.createGridView = async function (cList) {
    let grp_comp = $c.gcm.getTestGroup();
    let ns = $c.gcm.getNameSpace();

    let s = '';
    s += '<w2:gridView ' + ns + ' ' + cList + ' checkAllType="false" id="" dataList="data:dlt_bind" style="width:520px;height:300px;" ev:oncellindexchange="scwin.target1_oncellindexchange">';
    s += '<w2:caption style="" id="caption1" value="focusMove 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="120" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    s += '<w2:column width="120" style="" inputType="text" id="col4" value=""></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// 셀 포커스 변경 시 호출 (oncellindexchange)
//  - 사용자가 셀 클릭 후 방향키/Enter/Tab/Home/End/PageUp/PageDown 입력 → 포커스 셀 변경 시 발생
//  - getFocusedRowIndex/getFocusedColumnIndex 로 현재 포커스 셀 위치를 하단에 출력
//  - focusMove 값에 따라 어느 키 입력에서 포커스가 이동(이벤트 발생)하는지 확인
scwin.target1_oncellindexchange = function (rowIndex, columnIndex, oldRow, oldColumnIndex) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    bottom.setReturnValue("현재 포커스 셀 → row : " + target1.getFocusedRowIndex()
        + ", column : " + target1.getFocusedColumnIndex());
}
